header-footer.scss:
@import "global-objects";

/* Twelve header: BigCommerce data, prototype presentation. */

.twelve-nav-item {
    &[nav-item="sustainably_sourced"] {
        display: none !important;
    }
}

.page_type__category .accordion-block:has([accordion-title="sustainably_sourced"]) {
    display: none;
}
.page_title__sustainably_sourced .accordion-block:has([accordion-title="sustainably_sourced"]) {
    display: flex;
}

.twelve-header {
    position: sticky;
    top: 0;
    height: auto;
    display: block;
    background: #fff;
    color: #000;
    border-bottom: 1px solid #e4e4e4;
    z-index: 100;

    a,
    button,
    summary {
        color: inherit;
    }
    a:focus-visible,
    button:focus-visible,
    summary:focus-visible {
        outline: 2px solid var(--royal) !important;
        outline-offset: 4px;
    }
    .navPages-container {
        display: none;
    }
    .header-logo {
        margin: 0;
        padding: 0;
        height: auto;
        grid-column: 2;
        grid-row: 1;
    }
    .header-logo__link {
        width: auto;
    }
    .header-logo-text {
        font-family: var(--word);
        color: #000;
        font-size: 48px;
        letter-spacing: -3px;
    }
    .header-logo-image-container {
        min-height: 0;
    }
    .header-logo-image,
    .header-logo-image-unknown-size {
        position: static;
        max-height: 56px;
        max-width: 200px;
    }
    .twelve-wordmark {
        width: 200px;
        height: auto;
        display: block;
    }
}
.twelve-masthead {
    max-width: 1512px;
    margin: 0 auto;
    padding: 0 56px;
    min-height: 104px;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    gap: 24px;
    align-items: center;
}
.twelve-announcement {
    background: #000;
    color: #fff;
    position: relative;
    z-index: 2;
}
.twelve-announcement-inner {
    max-width: 1512px;
    padding: 0 56px;
    margin: auto;
    min-height: 38px;
    display: grid;
    grid-template-columns: 0fr 2fr 1fr;
    gap: 0;
    align-items: center;
}
.twelve-announcement-message {
    grid-column: 2;
    text-align: left;
    font: 500 12px/1.4 var(--sans-ext);
    text-transform: uppercase;
    padding: 8px 0;
    padding-right: 20px;
    @include sm-desktop{
        text-align: center;
        padding-right: 0;
    }
}
.twelve-localization {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 22px;
    white-space: nowrap;
    font: 500 10px/1.4 var(--sans-ext);
    text-transform: uppercase;
    .navUser-section {
        margin: 0;
        float: none;
    }
    .navUser-item {
        display: block;
        float: none;
    }
    .navUser-action {
        min-width: 52px;
        font: inherit;
        border: 1px solid #454545;
        padding: 4px 12px;
        text-align: center;
    }
    .dropdown-menu {
        background: #fff;
        color: #000;
        text-transform: none;
        min-width: 150px;
    }
    .dropdown-menu a {
        display: block;
        padding: 8px 12px;
    }
}
.twelve-localization-group {
    display: flex;
    align-items: center;
    gap: 9px;
}
.twelve-localization-label {
    color: rgba(255, 255, 255, 0.52);
    font-size: 8.5px;
}
.twelve-language-static {
    min-width: 52px;
    padding: 4px 10px;
    border: 1px solid #454545;
    color: #fff;
    text-align: center;
}
.twelve-localization #currencySelection {
    top: calc(100% + 1px) !important;
    left: 50% !important;
    right: auto !important;
    min-width: 120px;
    padding: 0;
    border: 1px solid #c9c9c9;
    background: #fff;
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.12);
    transform: translateX(-50%);
    z-index: 120;
}
.twelve-localization #currencySelection::before,
.twelve-localization #currencySelection::after {
    display: none;
}
.twelve-localization #currencySelection .dropdown-menu-item {
    display: block;
    width: 100%;
    margin: 0;
    padding: 0;
}
.twelve-localization #currencySelection a {
    display: block;
    width: 100%;
    margin: 0;
    padding: 9px 12px;
    box-sizing: border-box;
    color: #000;
    font: 500 10px/1.2 var(--sans-ext);
    text-align: left;
    white-space: nowrap;
}
.twelve-localization #currencySelection a:hover,
.twelve-localization #currencySelection a:focus {
    background: #1f65d6;
    color: #fff;
}
.twelve-nav-list {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px 25px;
    list-style: none;
    margin: 0;
}
.twelve-nav-link,
.twelve-menu > summary {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 12px 0;
    font: 500 14px/1.4 var(--sans-ext);
    text-transform: uppercase;
    cursor: pointer;
    list-style: none;
    border: 0;
    background-image: linear-gradient(#000, #000);
    background-position: 0 calc(100% - 6px);
    background-repeat: no-repeat;
    background-size: 0% 1px;
    transition: background-size 0.35s cubic-bezier(0.22, 0.61, 0.36, 1);
    @include minmid-desktop{
        font: 500 16px/1.4 var(--sans-ext);
    }
}

.twelve-menu > summary::-webkit-details-marker {
    display: none;
}
.twelve-menu > summary:hover,
.twelve-menu[open] > summary,
.twelve-nav-link:hover,
.twelve-nav-link.activePage,
.twelve-nav-link[aria-current] {
    background-size: 100% 1px;
}
.twelve-chevron {
    margin-top: -3px;
    width: 7px;
    height: 7px;
    border-right: 1px solid;
    border-bottom: 1px solid;
    transform: translateY(-2px) rotate(45deg);
    transition: transform 0.3s cubic-bezier(0.22, 0.61, 0.36, 1);
}
.twelve-menu[open] .twelve-chevron {
    transform: translateY(0) rotate(-135deg);
}
.twelve-mega {
    position: absolute;
    left: 0;
    right: 0;
    top: 100%;
    background: #fff;
    border-top: 1px solid #e4e4e4;
    box-shadow: 0 30px 60px -40px #0006;
    max-height: calc(100dvh - 144px);
    overflow-y: auto;
}
.twelve-mega-inner {
    max-width: 1512px;
    margin: auto;
    padding: 48px 56px;
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr)) minmax(0, 1.05fr);
    gap: 32px;
    align-items: start;
}
.twelve-mega-column > summary {
    margin: 0 0 16px;
    padding: 0 0 14px;
    border-bottom: 1px solid #e4e4e4;
    font: 500 14px/1.4 var(--sans-ext);
    text-transform: uppercase;
    list-style: none;
}
.twelve-mega-column > summary::-webkit-details-marker {
    display: none;
}
.twelve-mega-column > summary .twelve-plus {
    display: none;
}
.twelve-mega-column > summary > a {
    color: inherit;
    font: inherit;
}
.twelve-category-all {
    display: none;
}
.twelve-mobile-secondary {
    display: none;
}
.twelve-mega ul {
    list-style: none;
    margin: 0;
}
.twelve-mega-column li > a {
    display: block;
    padding: 7px 0;
    font: 400 14.5px/1.4 var(--serif);
    color: #000000;
}
.twelve-brand-list a {
    display: block;
    padding: 7px 0;
    font: 400 14.5px/1.3 var(--serif);
    color: #000000;
}
.twelve-mega-column li > a:hover,
.twelve-brand-list a:hover {
    color: #454545;
    text-decoration: none !important;
}
.twelve-mega-column ul ul {
    padding-left: 14px;
}
.twelve-mega-all {
    grid-column: -2;
    border-left: 1px solid #e4e4e4;
    padding-left: 15px;
    display: grid;
    gap: 14px;
    align-content: start;
    font: 400 14.5px/1.45 var(--serif);
    color: #000000;
}
.twelve-mega-all p {
    margin: 0;
    max-width: 26ch;
}
.twelve-eyebrow {
    font: 500 14px/1.2 var(--sans-ext);
    letter-spacing: 0.025em;
    text-transform: uppercase;
    color: #000000;
}
.twelve-all-link {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    justify-self: start;
    min-height: 40px;
    padding: 10px 12px;
    overflow: hidden;
    border: 1px solid #000;
    background: transparent;
    color: #000 !important;
    font: 500 12px/1.4 var(--sans-ext);
    letter-spacing: 0.025em;
    text-transform: uppercase;
    text-align: center;
    white-space: nowrap;
    transition: color 0.35s cubic-bezier(0.22, 0.61, 0.36, 1);
}
.twelve-all-link::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    background: #000;
    transform: translateY(101%);
    transition: transform 0.35s cubic-bezier(0.22, 0.61, 0.36, 1);
}
.twelve-all-link > span {
    position: relative;
    z-index: 1;
}
.twelve-all-link:hover,
.twelve-all-link:focus-visible {
    color: #fff !important;
}
.twelve-all-link:hover::after,
.twelve-all-link:focus-visible::after {
    transform: translateY(0);
}
.twelve-text-link {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    justify-self: start;
    margin-top: 4px;
    padding: 0 0 5px;
    font: 500 12px/1.2 var(--sans-ext);
    letter-spacing: 0.025em;
    text-transform: uppercase;
    color: #000;
    background-image: linear-gradient(#000, #000);
    background-position: 0 100%;
    background-repeat: no-repeat;
    background-size: 100% 1px;
    transition: background-size 0.35s cubic-bezier(0.22, 0.61, 0.36, 1);
}
.twelve-text-link:hover,
.twelve-text-link:focus-visible {
    background-size: 0% 1px;
}
.twelve-text-link > span {
    display: inline-block;
    transition: transform 0.35s cubic-bezier(0.22, 0.61, 0.36, 1);
}
.twelve-text-link:hover > span,
.twelve-text-link:focus-visible > span {
    transform: translateX(5px);
}
.twelve-mega-brand-promo .twelve-eyebrow {
    color: #000;
}
.twelve-mega-brand-promo p {
    max-width: none;
}
.twelve-mega-brands {
    grid-template-columns: minmax(0, 3.4fr) minmax(0, 1.25fr);
    gap: 48px;
}
.twelve-brand-list {
    columns: 4;
    column-gap: 48px;
}
.twelve-brand-list li {
    break-inside: avoid;
}
.twelve-mega-brands .twelve-mega-all {
    grid-column: 2;
}
.twelve-header .twelve-tools {
    grid-column: 3;
    grid-row: 1;
    position: static;
    transform: none;
    padding: 0;
    width: auto;
    z-index: auto;
    .navUser-section {
        position: static;
        display: flex;
        justify-content: flex-end;
        float: none;
        margin: 0;
        gap: 6px;
    }
    .navUser-item {
        display: block;
        float: none;
    }
    .twelve-tool {
        width: 44px;
        height: 44px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 0;
        position: relative;
    }
    .twelve-tool svg {
        width: 26px;
        height: 26px;
        stroke: #000;
        stroke-width: 1.3;
        fill: none;
        stroke-linecap: round;
        stroke-linejoin: round;
    }
    .twelve-tool:hover {
        opacity: 0.6;
    }
    .cart-quantity {
        position: absolute;
        top: 0;
        right: 0;
        margin: 0;
        width: auto;
        min-width: 16px;
        height: 14px;
        padding: 0 3px;
        border-radius: 0;
        font: 700 9px/14px var(--sans-ext);
        background: #000;
        color: #fff;
        text-align: center;
    }
    .dropdown--quickSearch {
        position: fixed;
        inset: 0 0 auto !important;
        width: 100% !important;
        height: auto;
        max-height: 100dvh;
        min-height: 0;
        padding: 0;
        border: 0;
        overflow-x: hidden;
        overflow-y: auto;
        overscroll-behavior: contain;
        background: #fff;
        box-shadow: 0 100vh 0 100vh rgba(0, 0, 0, 0.42);
        z-index: 200;
    }
    #cart-preview-dropdown {
        max-width: calc(100vw - 32px);
    }
}
.twelve-search-overlay {
    max-width: 1512px;
    margin: 0 auto;
    padding: 38px 56px 56px;
}
.twelve-search-overlay .form {
    max-width: none !important;
    margin: 0;
}
.twelve-search-overlay .form-fieldset {
    margin: 0;
}
.twelve-search-overlay .form-field {
    position: relative;
    display: flex;
    align-items: center;
    margin: 0;
    border-bottom: 1px solid #000;
}
.twelve-search-icon {
    flex: 0 0 auto;
    width: 22px;
    height: 22px;
    margin-right: 24px;
    fill: none;
    stroke: #000;
    stroke-width: 1.3;
}
.twelve-search-overlay .form-input {
    height: 80px !important;
    padding: 0;
    border: 0;
    box-shadow: none;
    font: 300 42px/1.1 var(--sans);
    color: #000;
}
.twelve-search-overlay .form-input::placeholder {
    color: #9b9b9b;
    opacity: 1;
}
.twelve-search-overlay .form-input:focus {
    border: 0;
    box-shadow: none;
    outline: none !important;
}
.twelve-search-close {
    flex: 0 0 42px;
    height: 42px;
    padding: 0;
    font: 300 40px/1 var(--sans);
}
.twelve-search-content {
    display: grid;
    grid-template-columns: 468px minmax(0, 1fr);
    gap: 48px;
    padding-top: 46px;
}
.twelve-search-label,
.twelve-search-products-title {
    display: block;
    margin: 0 0 14px;
    font: 500 12px/1.2 var(--sans-ext);
    letter-spacing: 0.025em;
    text-transform: uppercase;
    color: #666;
}
.twelve-search-products-title em {
    font: italic 400 14px/1.2 var(--serif);
}
.twelve-search-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}
.twelve-search-tags button {
    min-height: 40px;
    padding: 10px 14px;
    border: 1px solid #c8c8c8;
    font: 400 14px/1.2 var(--serif);
}
.twelve-search-tags button:hover {
    border-color: #000;
}
.twelve-search-tags button.is-active {
    border-color: #000;
    background: #000;
    color: #fff;
}
.twelve-search-products {
    position: relative;
}
.twelve-search-products .loadingOverlay {
    position: absolute;
    inset: 34px 0 0;
    z-index: 3;
    background-color: rgba(255, 255, 255, 0.82);
}
.twelve-search-products .quickSearchResults {
    margin: 0;
    .card-wishlist {
        display: none !important;
    }
}
.twelve-search-products .productGrid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 48px;
    margin: 0;
    padding: 18px 0 0 !important;
}
.twelve-search-products .productGrid::before,
.twelve-search-products .productGrid::after {
    display: none;
}
.twelve-search-products .product {
    width: auto;
    padding: 0;
}
.twelve-search-products .card {
    margin: 0;
}
.twelve-search-products .card.card--alternate,
.twelve-search-products .card.card--alternate:hover,
.twelve-search-products .card.card--alternate:focus-within {
    border: 0;
    box-shadow: none;
}
.twelve-search-products .card.card--alternate .card-body,
.twelve-search-products .card.card--alternate:hover .card-body,
.twelve-search-products .card.card--alternate:focus-within .card-body {
    padding: 15px 0 0;
    background: transparent;
    color: #111;
}
.twelve-search-products .card.card--alternate:hover .card-title > a,
.twelve-search-products .card.card--alternate:focus-within .card-title > a {
    color: #111;
}
.twelve-search-products .card.card--alternate:hover .card-text,
.twelve-search-products .card.card--alternate:focus-within .card-text {
    color: inherit;
}
.twelve-search-products .card-figure {
    margin: 0 0 20px;
}
.twelve-search-products .card-title {
    font: 400 16px/1.3 var(--serif);
}
.twelve-search-products .card-text {
    font-size: 14px;
}
.twelve-search-products .modal-close {
    display: none;
}
.twelve-search-products .quickSearchMessage {
    margin: 38px 0 0;
    text-align: left;
    font: italic 400 16px/1.4 var(--serif);
    color: #666;
}
.twelve-header .dropdown--quickSearch.is-open {
    animation: twelve-search-open 0.45s cubic-bezier(0.22, 0.61, 0.36, 1) both;
}
.twelve-header .dropdown--quickSearch.is-open.is-closing {
    animation: twelve-search-close 0.45s cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

@media (max-width: 991px) {
    .twelve-header .dropdown--quickSearch {
        height: auto;
        max-height: 100dvh;
        overflow-y: auto;
        box-shadow: 0 100vh 0 100vh rgba(0, 0, 0, 0.42);
    }
    .twelve-search-overlay {
        width: 100%;
        padding: 20px 20px 40px;
    }
    .twelve-search-icon {
        width: 18px;
        height: 18px;
        margin-right: 16px;
    }
    .twelve-search-overlay .form-input {
        height: 64px !important;
        min-width: 0;
        font-size: 26px;
    }
    .twelve-search-close {
        flex-basis: 28px;
        width: 28px;
        height: 28px;
        font-size: 16px;
    }
    .twelve-search-content {
        display: block;
        padding-top: 30px;
    }
    .twelve-search-label,
    .twelve-search-products-title {
        margin-bottom: 16px;
        font-size: 10px;
    }
    .twelve-search-tags {
        gap: 8px;
    }
    .twelve-search-tags button {
        min-height: 38px;
        padding: 9px 15px;
        font-size: 14px;
    }
    .twelve-search-products {
        margin-top: 34px;
    }
    .twelve-search-products .productGrid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 32px 16px;
        padding-top: 16px !important;
    }
    .twelve-search-products .card-figure {
        margin-bottom: 16px;
    }
    .twelve-search-products .card-title {
        font-size: 16px;
    }
    .twelve-search-products .quickSearchMessage {
        margin-top: 24px;
        font-size: 15px;
    }
}

@keyframes twelve-search-open {
    from {
        transform: translateY(-100%);
    }
    to {
        transform: translateY(0);
    }
}
@keyframes twelve-search-close {
    from {
        transform: translateY(0);
    }
    to {
        transform: translateY(-100%);
    }
}
@media (prefers-reduced-motion: reduce) {
    .twelve-header .dropdown--quickSearch.is-open,
    .twelve-header .dropdown--quickSearch.is-open.is-closing {
        animation-duration: 0.01ms;
    }
}

/* Twelve static footer; the newsletter submission remains BigCommerce-powered. */
.twelve-footer {
    background: #000;
    color: #fff;
}
.twelve-footer-top {
    max-width: 1512px;
    margin: 0 auto;
    padding: 96px 56px 64px;
    display: grid;
    grid-template-columns: 1.6fr 1fr 1fr 1fr 1.3fr;
    gap: 48px;
    align-items: start;
}
.twelve-footer-wordmark {
    display: block;
    font: 400 42px/1 var(--word);
    letter-spacing: -2px;
}
.twelve-footer-brand p,
.twelve-footer-newsletter p {
    margin: 24px 0 0;
    max-width: 32ch;
    font: 400 15px/1.45 var(--serif);
    color: rgba(255, 255, 255, 0.8);
}
.twelve-footer-brand > span:last-child {
    display: block;
    margin-top: 32px;
    font: 500 10px/1.4 var(--sans-ext);
    letter-spacing: 0.025em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.42);
}
.twelve-footer-column h2 {
    margin: 0 0 24px;
    font: 500 14px/1.2 var(--sans-ext);
    letter-spacing: 0.025em;
    text-transform: uppercase;
    color: #fff;
}
.twelve-footer-column > button {
    display: none;
}
.twelve-footer-column ul {
    margin: 0;
    padding: 0;
    list-style: none;
}
.twelve-footer-column li {
    margin: 0;
    padding: 0;
}
.twelve-footer-column li a {
    display: block;
    padding: 7px 0;
    font: 400 15px/1.35 var(--serif);
    color: rgba(255, 255, 255, 0.78);
    transition:
        color 0.2s,
        padding-left 0.3s cubic-bezier(0.22, 0.61, 0.36, 1);
}
.twelve-footer-column li a:hover {
    padding-left: 6px;
    color: #fff;
}
.twelve-footer-newsletter p {
    margin: 0 0 14px;
}
.twelve-footer-newsletter form {
    display: flex;
    align-items: center;
    border-bottom: 1px solid rgba(255, 255, 255, 0.4);
}
.twelve-footer-newsletter form input[type="email"] {
    flex: 1;
    min-width: 0;
    padding: 9px 0;
    border: 0;
    background: none;
    box-shadow: none;
    color: #fff;
    font: 400 14px/1.4 var(--serif);
}
.twelve-footer-newsletter form input[type="email"]::placeholder {
    color: rgba(255, 255, 255, 0.4);
}
.twelve-footer-newsletter form button {
    padding: 9px 0 9px 12px;
    color: #fff;
    font-size: 15px;
}
.twelve-footer-bar {
    border-top: 1px solid rgba(255, 255, 255, 0.14);
}
.twelve-footer-bar > div {
    max-width: 1512px;
    margin: 0 auto;
    padding: 24px 56px;
    display: flex;
    align-items: center;
    justify-content: space-between;
