        width: 13px;
        left: 0;
        top: 6px;
    }
    .twelve-plus::after {
        height: 13px;
        width: 1px;
        left: 6px;
        top: 0;
        transition: transform 0.2s;
    }
    details[open] > summary > .twelve-plus::after {
        transform: scaleY(0);
    }
    .twelve-mobile-groups {
        padding-bottom: 16px;
    }
    .twelve-mobile-groups > li {
        border-bottom: 1px solid #e4e4e4;
    }
    .twelve-mobile-groups > li:last-child {
        border-bottom: 0;
    }
    .twelve-mobile-subgroup > summary,
    .twelve-mobile-category-link {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 10px;
        padding: 14px 0;
        font: 400 16px/1.2 var(--serif);
        color: #454545;
        cursor: pointer;
    }
    .twelve-mobile-subgroup .twelve-plus {
        width: 11px;
        height: 11px;
        flex-basis: 11px;
        color: #767676;
    }
    .twelve-mobile-subgroup .twelve-plus::before {
        width: 11px;
        top: 5px;
    }
    .twelve-mobile-subgroup .twelve-plus::after {
        height: 11px;
        left: 5px;
    }
    .twelve-mobile-links {
        padding-bottom: 16px;
    }
    .twelve-mobile-links a {
        display: block;
        font: 400 16px/1.4 var(--serif);
        color: #454545;
        padding: 11px 0;
    }
    .twelve-mobile-subgroup > .twelve-mobile-links {
        padding-left: 24px;
    }
    .twelve-mobile-subgroup > .twelve-mobile-links a {
        font-size: 15px;
        padding: 9px 0;
    }
    .twelve-mobile-body a.twelve-mobile-all {
        display: block;
        padding: 12px 0;
        font: 500 10px/1.5 var(--sans-ext);
        text-transform: uppercase;
        color: #000;
    }
    .twelve-mobile-secondary {
        padding-top: 22px;
        display: grid;
        gap: 14px;
        font: 400 14px/1.4 var(--serif);
        color: #454545;
    }
    .twelve-mobile-footer {
        display: flex;
        flex: 0 0 auto;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        border-top: 1px solid #e4e4e4;
        padding: 18px 20px;
        padding-bottom: calc(18px + env(safe-area-inset-bottom, 0px));
        background: #fff;
    }
    .twelve-mobile-selectors {
        display: flex;
        align-items: center;
        gap: 16px;
    }
    .twelve-mobile-select {
        position: relative;
    }
    .twelve-mobile-select > summary,
    .twelve-mobile-locale {
        display: block;
        margin: 0;
        border: 1px solid #c9c9c9;
        padding: 7px 12px;
        border-radius: 0;
        font: 500 9.5px/1.2 var(--sans-ext);
        color: #454545;
        text-transform: uppercase;
    }
    .twelve-mobile-select > summary {
        cursor: pointer;
    }
    .twelve-mobile-select ul {
        position: absolute;
        bottom: calc(100% + 8px);
        left: 0;
        min-width: 100px;
        max-height: 180px;
        overflow-y: auto;
        margin: 0;
        list-style: none;
        border: 1px solid #c9c9c9;
        background: #fff;
        box-shadow: 0 8px 24px #0001;
    }
    .twelve-mobile-select li a {
        display: block;
        padding: 10px 12px;
        font: 500 10px/1.4 var(--sans-ext);
    }
    .twelve-mobile-select li a[aria-current] {
        font-weight: 700;
        background: #f7f6f4;
    }
    .twelve-mobile-cities {
        font: 300 10px/1.4 var(--sans);
        color: #767676;
        white-space: nowrap;
    }
}
@media (prefers-reduced-motion: reduce) {
    .twelve-header *,
    .twelve-header *::before,
    .twelve-header *::after {
        transition: none !important;
    }
}

